    @Test fun batchExportUsesOneFileIndependentGenerationsAndTruthfulStatuses()=runTest{
        val a=outbox("A");val b=outbox("B");val c=outbox("C");val d=outbox("D");val e=outbox("E")
        service.createExportFile(listOf(c,d,e),"Office",root);service.rescheduleOutboxVisit(d,"2026-09-15","10:00","Europe/Bucharest");service.concludeOutboxVisits(listOf(e))
        val before=root.resolve("work-packages").listFiles{f->f.extension=="slwork"}.orEmpty().size
        val artifact=service.createExportFile(listOf(a,c,d),"Office",root);val decoded=DispatchPackageCodec.decode(artifact.file.readBytes());assertEquals(setOf(a,c,d),decoded.visits.map{it.dispatchVisitId}.toSet());assertFalse(decoded.visits.any{it.dispatchVisitId in setOf(b,e)});assertEquals(1,decoded.visits.single{it.dispatchVisitId==a}.generation);assertEquals(1,decoded.visits.single{it.dispatchVisitId==c}.generation);assertEquals(2,decoded.visits.single{it.dispatchVisitId==d}.generation);assertEquals(before+1,root.resolve("work-packages").listFiles{f->f.extension=="slwork"}.orEmpty().size);assertEquals(DispatchOutboxStatus.DISPATCHED,service.outboxVisits().single{it.dispatchVisitId==a}.outboxStatus);assertEquals(DispatchOutboxStatus.DRAFT,service.outboxVisits().single{it.dispatchVisitId==b}.outboxStatus);assertEquals(DispatchOutboxStatus.CONCLUDED,service.outboxVisits().single{it.dispatchVisitId==e}.outboxStatus)
    }

    @Test fun exportFailuresAndStalePreparationNeverAdvanceStatus()=runTest{
        suspend fun verify(checkpoint:String,failure:Throwable){val id=outbox(checkpoint);val failing=DispatchPackageService(db,root,DispatchMutationFault{if(it==checkpoint)throw failure});val thrown=runCatching{failing.createExportFile(listOf(id),"Office",root)}.exceptionOrNull();assertEquals(failure::class,thrown!!::class);val value=db.dispatchDao().outboxVisit(id)!!;assertEquals(DispatchOutboxStatus.DRAFT,value.outboxStatus);assertNull(value.lastExportedGeneration)}
        verify("before_export_file_write",IllegalStateException("write failed"));verify("after_export_file_write_before_commit",IllegalStateException("commit stopped"));verify("before_export_file_write",CancellationException("cancelled"))
        val stale=outbox("STALE");val prepared=service.prepareExport(listOf(stale),"Office");service.rescheduleOutboxVisit(stale,"2026-09-16","11:00","Europe/Bucharest");assertThrows(IllegalArgumentException::class.java){kotlinx.coroutines.runBlocking{service.commitPreparedExport(prepared)}};assertEquals(DispatchOutboxStatus.DRAFT,db.dispatchDao().outboxVisit(stale)!!.outboxStatus)
    }

    @Test fun concludeReopenAreAtomicAndNeverChangeGeneration()=runTest{
        val draft=outbox("DRAFT");assertThrows(IllegalArgumentException::class.java){kotlinx.coroutines.runBlocking{service.concludeOutboxVisits(listOf(draft))}}
        val ids=(1..10).map{outbox("STATUS-$it")};service.createExportFile(ids,"Office",root);val generations=ids.associateWith{db.dispatchDao().outboxVisit(it)!!.lastExportedGeneration};service.concludeOutboxVisits(ids);assertTrue(ids.all{db.dispatchDao().outboxVisit(it)!!.outboxStatus==DispatchOutboxStatus.CONCLUDED});assertThrows(IllegalArgumentException::class.java){kotlinx.coroutines.runBlocking{service.concludeOutboxVisits(listOf(ids.first(),draft))}};assertEquals(DispatchOutboxStatus.DRAFT,db.dispatchDao().outboxVisit(draft)!!.outboxStatus);service.reopenOutboxVisits(ids);assertTrue(ids.all{db.dispatchDao().outboxVisit(it)!!.outboxStatus==DispatchOutboxStatus.DISPATCHED});assertEquals(generations,ids.associateWith{db.dispatchDao().outboxVisit(it)!!.lastExportedGeneration});service.createExportFile(listOf(ids.first()),"Office",root);assertEquals(1,db.dispatchDao().outboxVisit(ids.first())!!.lastExportedGeneration);service.rescheduleOutboxVisit(ids.first(),"2026-09-20",null,"Europe/Bucharest");service.createExportFile(listOf(ids.first()),"Office",root);assertEquals(2,db.dispatchDao().outboxVisit(ids.first())!!.lastExportedGeneration)
    }

