        val self=service.identity();val tech=DispatchTechnicianSnapshot(self.technicianId,self.name);val team=DispatchTeamSnapshot("T","Team",listOf(self.technicianId),emptyList());val dao=db.serviceLoopDao();dao.insertCustomers(listOf(CustomerEntity("LC","CU-X","Customer X")));dao.insertSites(listOf(SiteEntity("LS","LC","ST-X","Site X",null,null)));dao.insertEquipment(listOf(EquipmentEntity("LE","LS","EQ-B",null,"Wrong equipment",null,null,"DIFFERENT",null)))
        fun visit(id:String,eq:String)=DispatchVisit(id,1,id,"2026-09-22",null,"Europe/Bucharest","ST-X",null,listOf(team),listOf(tech),emptyList(),listOf(DispatchWork("I-$id",eq,"Inspect",assignedTechnicians=listOf(tech))))
        val batch=DispatchPackage("DIR-BATCH",Instant.now().toString(),"Office",listOf(DispatchCustomer("CU-X","Customer X")),listOf(DispatchSite("ST-X","CU-X","Site X",null)),listOf(DispatchEquipment("EQ-A","ST-X","Safe equipment",null,null,null,"A"),DispatchEquipment("EQ-B","ST-X","Incoming equipment",null,null,null,"B")),listOf(visit("V-A","EQ-A"),visit("V-B","EQ-B")));val preview=service.preview(batch);assertEquals(listOf("V-A"),preview.safeActionableVisits.map{it.dispatchVisitId});service.import(preview);assertNotNull(db.dispatchDao().visitBinding("V-A"));assertNull(db.dispatchDao().visitBinding("V-B"));assertEquals("Wrong equipment",dao.equipment("LE")!!.name)
        dao.insertSites(listOf(SiteEntity("LS2","LC","ST-SHARED","Different local name",null,null)));val shared=batch.copy(packageId="SHARED",sites=listOf(DispatchSite("ST-SHARED","CU-X","Incoming shared site",null)),equipment=listOf(DispatchEquipment("EQ-C","ST-SHARED","C",null,null,null,null),DispatchEquipment("EQ-D","ST-SHARED","D",null,null,null,null)),visits=listOf(visit("V-C","EQ-C").copy(siteReference="ST-SHARED"),visit("V-D","EQ-D").copy(siteReference="ST-SHARED")));val sharedPreview=service.preview(shared);assertTrue(sharedPreview.safeActionableVisits.isEmpty());assertTrue(sharedPreview.visits.all{sharedPreview.directoryBlockers(it).any{x->x.reference=="ST-SHARED"}})
    }

